SourceCode.Declaration:
/// <summary>
/// CB166_SalesOrderSubstitutes
/// Similar to PriceDiscCacheKey, provides the logic for creating a cache key that holds
/// values used for searching substitutes.
/// </summary>
class METSalesItemSubstituteCacheKey
{
    public METSalesItemSubstitutionAccountCodeType  accountCode;
    public CustVendRel                              accountRel;
    public TableGroupAll                            siteCode;
    public InventSiteId                             siteRel;
    public ItemId                                   itemId;

}

Method.Source:
public static METSalesItemSubstituteCacheKey construct()
{
    return new METSalesItemSubstituteCacheKey();
}

    /// <summary>
    /// Initializes the <c>METSalesItemSubstituteCacheKey</c>.
    /// </summary>
    /// <param name = "_siteCode">The site code.</param>
    /// <param name = "_siteRel">An <c>InventSiteId</c> value.</param>
    /// <param name = "_accountCode">The account code.</param>
    /// <param name = "_accountRel">The customer or customer operations group id.</param>
    /// <param name = "_itemId">Item number.</param>
    public void initialize(
        TableGroupAll                           _siteCode,
        InventSiteId                            _siteRel,
        METSalesItemSubstitutionAccountCodeType _accountCode,
        CustVendRel                             _accountRel,
        ItemId                                  _itemId)
    {

        this.siteCode                   = _siteCode;
        this.siteRel                    = _siteRel;
        this.accountCode                = _accountCode;
        this.accountRel                 = _accountRel;
        this.itemId                     = _itemId;
    }

    /// <summary>
    /// Composes a key based of the passed values and the current data area id.
    /// </summary>
    /// <returns>A container representing the key</returns>
    public container pack()
    {
        str key;

        key = curext()                      +
              ' '                           +
              int2str(siteCode)             +
              ' '                           +
              siteRel                       +
              ' '                           +
              int2str(accountCode)          +
              ' '                           +
              accountRel                    +
              ' '                           +
              itemId;

        return [key];
    }

/// <summary>
/// Remove a substitute from the cache if the substitute record was created/updated/deleted
/// </summary>
/// <param name = "_salesItemSubstitute"><c>METSalesItemSubstitute</c> record</param>
static void removeSalesItemSubstituteCache(METSalesItemSubstitute _salesItemSubstitute)
{
    METSalesItemSubstituteCacheKey::flushSelectedSalesItemSubstituteCache(_salesItemSubstitute);
}

    /// <summary>
    /// Remove a substitute key from the cache
    /// </summary>
    /// <param name = "_salesItemSubstitute"><c>METSalesItemSubstitute</c> record</param>
    private static void flushSelectedSalesItemSubstituteCache(METSalesItemSubstitute _salesItemSubstitute)
    {
        METSalesItemSubstituteCacheKey cacheKey = METSalesItemSubstituteCacheKey::construct();
        TableGroupAll siteCode = _salesItemSubstitute.InventSiteId ? TableGroupAll::Table : TableGroupAll::All;

        cacheKey.initialize(siteCode, _salesItemSubstitute.InventSiteId, _salesItemSubstitute.AccountCode, _salesItemSubstitute.AccountRelation, _salesItemSubstitute.ItemId);

        METSalesItemSubstituteCacheKey::removeFindSubstituteGlobalObjectCache(cacheKey);
    }

/// <summary>
///    Retrieves an object from the <c>SysGlobalObjectCache</c> object.
/// </summary>
/// <param name="_scope">
///    A string type that specifies the scope or the owner of the cached object.
/// </param>
/// <param name="_key">
///    A container type that specifies the key to the cached object.
/// </param>
/// <returns>
///    A container type that specifies the retrieved object.
/// </returns>
public static container getSalesItemSubstituteCacheValue(str _scope, container _key)
{
    SysGlobalObjectCache sysGlobalObjectCache = new SysGlobalObjectCache();
    return sysGlobalObjectCache.find(_scope, _key);
}

/// <summary>
///    Inserts an object to the <c>SysGlobalObjectCache</c> object.
/// </summary>
/// <param name="_scope">
///    A string type that specifies the scope or the owner of the cached object.
/// </param>
/// <param name="_key">
///    A container type that specifies the key to the cached object.
/// </param>
/// <param name="_value">
///    A container type that has the object to cache.
/// </param>
public static void insertPriceDiscCache(str _scope, container _key, container _value)
{
    SysGlobalObjectCache sysGlobalObjectCache = new SysGlobalObjectCache();
    sysGlobalObjectCache.insert(_scope, _key, _value);
}

    /// <summary>
    /// Remove key from the cache
    /// </summary>
    /// <param name = "_cacheKey"><c>METSalesItemSubstituteCacheKey</c> to remove from the cache</param>
    private static void removeFindSubstituteGlobalObjectCache(METSalesItemSubstituteCacheKey _cacheKey)
    {
        container key = _cacheKey.pack();

        SysGlobalObjectCache sysGlobalObjectCache = new SysGlobalObjectCache();

        if (sysGlobalObjectCache.find(METSalesItemSubstituteSearch::retrieveCacheScope(), key) != conNull())
        {
            sysGlobalObjectCache.remove(METSalesItemSubstituteSearch::retrieveCacheScope(), key);
        }
    }
